android.extraProguardRules:
# ===== Planibble ProGuard/R8 keep rules =====
# Keep AdMob public API — reflection + GMS internals require these classes intact.
-keep public class com.google.android.gms.ads.** { public *; }
-keep public class com.google.ads.** { public *; }
-dontwarn com.google.android.gms.ads.**

# Keep RevenueCat public API — purchases SDK uses reflection for events + mappers.
-keep class com.revenuecat.purchases.** { *; }
-keep interface com.revenuecat.purchases.** { *; }
-dontwarn com.revenuecat.purchases.**

# Keep Expo modules — bridge resolution happens by class name.
-keep class expo.modules.** { *; }
-keep class expo.** { *; }
-dontwarn expo.modules.**

# Keep classes referenced by notification channels and boot receiver.
-keep class * extends android.content.BroadcastReceiver
-keep class * extends android.app.Service
